# block C (regime filters) and E (clocks), each on top of a1_bull (1h supertrend standard bullish | twin bearish)
cell("c1_spyup", "a1 + SPY above its open | twin + SPY below open", BULL + SPY_UP, BEAR + SPY_DN)
cell("c2_spypc", "a1 + SPY above prior close | twin + below prior close", BULL + SPY_PC_UP, BEAR + SPY_PC_DN)
cell("c3_gapup", "a1 + ticker gapped up (gap_pct >= 0) | twin + gapped down", BULL + GAP_UP, BEAR + GAP_DN)
cell("c4_band", "a1 + SPY-flat band (cross_1m in [-0.4,0.4]) | twin = shorts without the band", BULL + BAND, BEAR, short_band=False)
cell("c5_vpin", "a1 + VPIN >= 0.217 | twin = shorts without the VPIN floor", BULL + VPIN, BEAR, short_vpin=False)
cell("c6_bandvpin", "a1 + band + VPIN (the full v18 filter mirror) | twin = shorts with neither", BULL + BAND + VPIN, BEAR, short_band=False, short_vpin=False)
cell("e1_1000", "a1, entries 10:00-11:30 (both sides)", BULL, BEAR, clock=("10:00", None))
cell("e2_0945", "a1, first 15 min excluded (both sides)", BULL, BEAR, clock=("09:45", None))
cell("e3_pre1000", "a1, entries 09:30-10:00 only (both sides)", BULL, BEAR, clock=(None, "10:00"))
